class Solution:
    def strongCandidates(self, votes: List[int]) -> List[int]:
        n = len(votes)
        out = []
        for i, x in enumerate(votes):
            if x in votes[:i]:
                continue
            if votes.count(x) > n // 3:
                out.append(x)
        return sorted(out)

