class Solution {
    public int[] strongCandidates(int[] votes) {
        int n = votes.length;
        List<Integer> out = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            boolean seen = false;
            for (int j = 0; j < i && !seen; j++) seen = votes[j] == votes[i];
            if (seen) continue;
            int c = 0;
            for (int x : votes) if (x == votes[i]) c++;
            if (c > n / 3) out.add(votes[i]);
        }
        Collections.sort(out);
        return out.stream().mapToInt(Integer::intValue).toArray();
    }
}

