class Solution {
public:
    vector<int> strongCandidates(vector<int>& votes) {
        int n = votes.size();
        vector<int> out;
        for (int i = 0; i < n; i++) {
            if (find(votes.begin(), votes.begin() + i, votes[i]) != votes.begin() + i) continue;
            if (count(votes.begin(), votes.end(), votes[i]) > n / 3) out.push_back(votes[i]);
        }
        sort(out.begin(), out.end());
        return out;
    }
};

