        for (int x : votes) count.merge(x, 1, Integer::sum);
        List<Integer> out = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : count.entrySet()) if (e.getValue() > votes.length / 3) out.add(e.getKey());
        Collections.sort(out);
        return out.stream().mapToInt(Integer::intValue).toArray();
