typedef struct { int key; int count; bool used; } Slot;

static unsigned slotOf(int key, unsigned mask) {
    unsigned long long h = (unsigned long long) (long long) key * 0x9E3779B97F4A7C15ULL;
    return (unsigned) (h >> 32) & mask;
}

int* strongCandidates(int* votes, int votesSize, int* returnSize) {
    unsigned cap = 1;
    while (cap < 2u * votesSize) cap <<= 1;
    Slot* count = calloc(cap, sizeof(Slot));
    for (int i = 0; i < votesSize; i++) {
        unsigned s = slotOf(votes[i], cap - 1);
        while (count[s].used && count[s].key != votes[i]) s = (s + 1) & (cap - 1);
        count[s].key = votes[i];
        count[s].used = true;
        count[s].count++;
    }
    int* out = malloc(2 * sizeof(int));
    *returnSize = 0;
    for (unsigned s = 0; s < cap; s++) if (count[s].used && count[s].count > votesSize / 3) out[(*returnSize)++] = count[s].key;
    if (*returnSize == 2 && out[0] > out[1]) { int t = out[0]; out[0] = out[1]; out[1] = t; }
    free(count);
    return out;
}

