class Solution {
    public int[] strongCandidates(int[] votes) {
        int a = 0, b = 0, ca = 0, cb = 0;
        for (int x : votes) {
            if (ca > 0 && x == a) ca++;
            else if (cb > 0 && x == b) cb++;
            else if (ca == 0) { a = x; ca = 1; }
            else if (cb == 0) { b = x; cb = 1; }
            else { ca--; cb--; }
        }
        int na = 0, nb = 0;
        for (int x : votes) {
            if (ca > 0 && x == a) na++;
            else if (cb > 0 && x == b) nb++;
        }
        List<Integer> out = new ArrayList<>();
        if (na > votes.length / 3) out.add(a);
        if (nb > votes.length / 3) out.add(b);
        Collections.sort(out);
        return out.stream().mapToInt(Integer::intValue).toArray();
    }
}

